-- `scope` matches the secret to the URL you ATTACH against.
CREATE SECRET my_flight (
  TYPE airport,
  scope 'grpc+tls://flight.example.com:8815',
  auth_token 'your-token'
);

ATTACH 'grpc+tls://flight.example.com:8815' AS remote (TYPE airport);

